def name_operands(region,address,operation):
 if region!='Station' or address!=0x6C0D:return operation
 for value,name in ((0x9839,'InterfaceState.EventCode'),(0x7B52,'DrawItemState.Index21'),(0x7BA9,'DrawItemState.Index12'),(0x7C1F,'DrawItemState.Index13'),(0x7C7F,'DrawItemState.Index14'),(0x7CB7,'DrawItemState.Index15'),(0x7D25,'DrawItemState.Index17'),(0x7D54,'DrawItemState.Index16'),(0x7CF9,'DrawItemState.Index18'),(0x7690,'SystemInfoState.ItemIndex'),(0x788D,'VariantPanelState.ItemIndex'),(0x9A89,'MenuCommandState.PeriodicCall')):
  operation=operation.replace('(#'+format(value,'04X')+')','(@'+name+')')
 return operation.replace('CALL #C85E','CALL @Station.CloseMenuOnRow.Entry').replace('CALL #C873','CALL @Station.DropItemDraw.Entry').replace('LD HL, #9A58','LD HL, @Station.EmptyCallback.Entry')
